
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_tpss_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_tpss", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.312729361418368e-02, -5.260683391538545e-02, -5.184984366979992e-02, -5.074302535250958e-02, -4.911190943310782e-02, -4.667982417693306e-02, -4.299328612064906e-02, -3.730544431179984e-02, -2.861397054448205e-02, -1.734011903773205e-02, -1.104003890419021e-02, -3.773944483416168e-02, -4.583958952686500e-02, -3.246282512910542e-02, -1.782166422784201e-02, -4.652095504462385e-03, -2.362097266621076e-04, -8.629486869402449e-07, -2.425690247194542e-10, -2.887440630300605e-15]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


